package erratum

// Use opens a resource via the given opener, calls Frob(input) on it, and
// guarantees the resource is closed exactly once, no matter what happens.
//
// If the opener fails with a TransientError, it keeps retrying. Any other
// open error is returned. If Frob panics with a FrobError, the resource's
// Defrob is called with the FrobError's defrobTag and the error is returned.
// Any other error panic is returned as-is.
func Use(opener ResourceOpener, input string) (err error) {
	var resource Resource
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		if _, ok := err.(TransientError); !ok {
			return err
		}
	}

	defer resource.Close()
	defer func() {
		r := recover()
		if r == nil {
			return
		}
		switch err := r.(type) {
		case FrobError:
			resource.Defrob(err.defrobTag)
		case error:
			// Non-FrobError error panic: nothing to defrob.
		default:
			panic(r)
		}
		// Use the named return value so the error is returned
		// after Close has run.
	}()

	resource.Frob(input)
	return nil
}

